-- Schema only; no user data. Used to test the legacy database transition.
CREATE TABLE "api_businessprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "business_name" varchar(200) NOT NULL, "business_type" varchar(32) NOT NULL, "preferred_provider" varchar(16) NOT NULL, "cloud_provider" varchar(50) NOT NULL, "default_model" varchar(128) NOT NULL, "description" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "discount_percent" decimal NOT NULL, "tax_rate" decimal NOT NULL, "organization_id" bigint NULL UNIQUE REFERENCES "organizations_organization" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "api_chatconversation" ("id" char(32) NOT NULL PRIMARY KEY, "owner_hash" varchar(64) NOT NULL, "title" varchar(160) NOT NULL, "model" varchar(256) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "organization_id" bigint NULL REFERENCES "organizations_organization" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "api_chatmemory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "owner_hash" varchar(64) NOT NULL, "category" varchar(16) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "source_conversation_id" char(32) NULL REFERENCES "api_chatconversation" ("id") DEFERRABLE INITIALLY DEFERRED, "content" text NOT NULL, CONSTRAINT "unique_chat_memory_per_owner" UNIQUE ("owner_hash", "content"));
CREATE TABLE "api_chatmemorypreference" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "owner_hash" varchar(64) NOT NULL UNIQUE, "enabled" bool NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "api_chatmessage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "role" varchar(16) NOT NULL, "content" text NOT NULL, "created_at" datetime NOT NULL, "conversation_id" char(32) NOT NULL REFERENCES "api_chatconversation" ("id") DEFERRABLE INITIALLY DEFERRED, "memory_count" smallint unsigned NOT NULL CHECK ("memory_count" >= 0), "images" text NOT NULL CHECK ((JSON_VALID("images") OR "images" IS NULL)), "references" text NOT NULL CHECK ((JSON_VALID("references") OR "references" IS NULL)));
CREATE TABLE "api_localmodelprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(256) NOT NULL UNIQUE, "context_window" integer unsigned NOT NULL CHECK ("context_window" >= 0), "supports_thinking" bool NOT NULL, "think_enabled" bool NOT NULL, "supports_vision" bool NOT NULL, "input_mode" varchar(16) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "api_menuitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "category" varchar(100) NOT NULL, "description" text NOT NULL, "price" decimal NOT NULL, "is_available" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "barcode" varchar(128) NOT NULL, "business_id" bigint NULL REFERENCES "api_businessprofile" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "api_order" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customer_name" varchar(200) NOT NULL, "notes" text NOT NULL, "status" varchar(32) NOT NULL, "subtotal" decimal NOT NULL, "discount" decimal NOT NULL, "tax" decimal NOT NULL, "total" decimal NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "business_id" bigint NOT NULL REFERENCES "api_businessprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "fulfillment_status" varchar(32) NOT NULL, "payment_status" varchar(32) NOT NULL, "review_note" text NOT NULL, "review_status" varchar(32) NOT NULL, "reviewed_at" datetime NULL, "reviewed_by" varchar(160) NOT NULL);
CREATE TABLE "api_orderitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "unit_price" decimal NOT NULL, "line_total" decimal NOT NULL, "menu_item_id" bigint NOT NULL REFERENCES "api_menuitem" ("id") DEFERRABLE INITIALLY DEFERRED, "order_id" bigint NOT NULL REFERENCES "api_order" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "organizations_dynamicform" ("id" char(32) NOT NULL PRIMARY KEY, "title" varchar(200) NOT NULL, "slug" varchar(180) NOT NULL, "description" text NOT NULL, "purpose" varchar(120) NOT NULL, "schema" text NOT NULL CHECK ((JSON_VALID("schema") OR "schema" IS NULL)), "status" varchar(16) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "organization_id" bigint NOT NULL REFERENCES "organizations_organization" ("id") DEFERRABLE INITIALLY DEFERRED, "visibility" varchar(16) NOT NULL, CONSTRAINT "unique_form_slug_per_org" UNIQUE ("organization_id", "slug"));
CREATE TABLE "organizations_dynamicform_allowed_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "dynamicform_id" char(32) NOT NULL REFERENCES "organizations_dynamicform" ("id") DEFERRABLE INITIALLY DEFERRED, "organizationgroup_id" bigint NOT NULL REFERENCES "organizations_organizationgroup" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "organizations_dynamicform_allowed_users" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "dynamicform_id" char(32) NOT NULL REFERENCES "organizations_dynamicform" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "organizations_dynamicform_editors" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "dynamicform_id" char(32) NOT NULL REFERENCES "organizations_dynamicform" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "organizations_formsubmission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "data" text NOT NULL CHECK ((JSON_VALID("data") OR "data" IS NULL)), "respondent_name" varchar(200) NOT NULL, "respondent_email" varchar(254) NOT NULL, "created_at" datetime NOT NULL, "form_id" char(32) NOT NULL REFERENCES "organizations_dynamicform" ("id") DEFERRABLE INITIALLY DEFERRED, "submitted_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "organization_id" bigint NOT NULL REFERENCES "organizations_organization" ("id") DEFERRABLE INITIALLY DEFERRED, "status" varchar(16) NOT NULL);
CREATE TABLE "organizations_organization" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "slug" varchar(180) NOT NULL UNIQUE, "description" text NOT NULL, "purpose" varchar(80) NOT NULL, "business_type" varchar(24) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "is_archived" bool NOT NULL, "profile_data" text NOT NULL CHECK ((JSON_VALID("profile_data") OR "profile_data" IS NULL)));
CREATE TABLE "organizations_organizationdocument" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "file" varchar(100) NOT NULL, "extracted_text" text NOT NULL, "created_at" datetime NOT NULL, "organization_id" bigint NOT NULL REFERENCES "organizations_organization" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "organizations_organizationgroup" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "alias" varchar(100) NOT NULL, "created_at" datetime NOT NULL, "organization_id" bigint NOT NULL REFERENCES "organizations_organization" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_org_group_alias" UNIQUE ("organization_id", "alias"));
CREATE TABLE "organizations_organizationgroup_members" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "organizationgroup_id" bigint NOT NULL REFERENCES "organizations_organizationgroup" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "organizations_organizationmembership" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "role" varchar(16) NOT NULL, "created_at" datetime NOT NULL, "organization_id" bigint NOT NULL REFERENCES "organizations_organization" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_org_membership" UNIQUE ("organization_id", "user_id"));
CREATE TABLE "organizations_personaldocument" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(160) NOT NULL, "kind" varchar(16) NOT NULL, "file" varchar(100) NOT NULL, "created_at" datetime NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "organizations_submissionattachment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "field_id" varchar(80) NOT NULL, "file" varchar(100) NOT NULL, "original_name" varchar(255) NOT NULL, "created_at" datetime NOT NULL, "submission_id" bigint NOT NULL REFERENCES "organizations_formsubmission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "organizations_userportfolio" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "phone_number" varchar(40) NOT NULL, "profile_data" text NOT NULL CHECK ((JSON_VALID("profile_data") OR "profile_data" IS NULL)), "use_for_form_assistance" bool NOT NULL, "updated_at" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "auto_update_from_submissions" bool NOT NULL);
